-- Fill missing/empty factory sections only; preserve existing editorial work. Safe to rerun.

INSERT INTO sf_content(content_key,ru,en,zh) SELECT 'factory_capabilities','','[]','[]' WHERE NOT EXISTS (SELECT 1 FROM sf_content WHERE content_key='factory_capabilities');

UPDATE sf_content SET en='[{"imageUrl":"/images/xj-wardrobe-2.jpg","altEn":"Wardrobe proportions and storage layout — AI design concept","altZh":"衣柜比例与收纳分区 · AI 设计示意","titleEn":"Start with the space","titleZh":"从空间出发，确认图纸","bodyEn":"Share room measurements, cabinet quantities and the objects you need to store. Door swing, skirting, sockets and access routes all affect the layout. Before sampling, agree the external dimensions, internal divisions and hardware positions so appearance and everyday use follow the same plan.","bodyZh":"提供空间尺寸、柜体数量和收纳需求，是项目的起点。开门方向、踢脚线、插座位置与搬运通道，都需要纳入布局考虑。打样前确认外部尺寸、内部层板分区及五金安装位置，让外观比例与日常使用相互配合。"},{"imageUrl":"/images/xj-material-v2.jpg","altEn":"Brushed metal and muted finishes — AI design concept","altZh":"拉丝金属与柔和表面色泽 · AI 设计示意","titleEn":"Choose the material and finish","titleZh":"材料与色泽，一起打磨","bodyEn":"Stainless steel and cold-rolled steel offer different starting points for a cabinet. Discuss the room environment, material grade, sheet thickness and finish together. A physical sample helps confirm colour, sheen and texture; screens and room lighting can change how a finish appears.","bodyZh":"不锈钢与冷轧钢，为金属柜带来不同的材料选择。结合使用环境，逐项沟通材质牌号、板材厚度与表面处理方案。通过实物样板确认颜色、光泽和触感，减少屏幕显示与空间光线带来的观感差异。"},{"imageUrl":"/images/xj-factory-v2.jpg","altEn":"Metal cabinet fabrication setting — AI illustration","altZh":"金属柜加工环境 · AI 示意图","titleEn":"Turn drawings into components","titleZh":"成型与表面，落实细节","bodyEn":"Cutting, bending and joining turn sheet material into cabinet components. Edge treatment, hole positions and fixing points deserve as much attention as the visible surfaces. Agree the forming and finishing sequence against the approved sample, including how exposed edges and contact areas should be handled.","bodyZh":"板材经过开料、折弯与连接，逐步形成柜体部件。除了可见表面，边缘处理、孔位与连接点同样影响装配效果。以确认样板为参照，沟通成型和表面处理顺序，并明确外露边缘、日常接触部位等细节要求。"},{"imageUrl":"/images/xj-kitchen-3.jpg","altEn":"Completed cabinet fronts and alignment — AI design concept","altZh":"成品柜门与整体对齐效果 · AI 设计示意","titleEn":"Check the details, plan the journey","titleZh":"装配检验，妥善交付","bodyEn":"Agree checks for cabinet dimensions, door gaps, drawer movement and visible finishes. Packing should suit the cabinet structure and the planned transport route, with attention to corners, surfaces and loose hardware. Confirm assembly format, carton labels and the packing list before dispatch arrangements are made.","bodyZh":"围绕柜体尺寸、门缝均匀度、抽屉开合与表面外观，确认成品检验项目。包装方式结合柜体结构及运输路线，关注边角、饰面与独立五金的保护。发运安排前，明确整装或拆装形式、外箱标识与装箱清单。"}]',zh='[{"imageUrl":"/images/xj-wardrobe-2.jpg","altEn":"Wardrobe proportions and storage layout — AI design concept","altZh":"衣柜比例与收纳分区 · AI 设计示意","titleEn":"Start with the space","titleZh":"从空间出发，确认图纸","bodyEn":"Share room measurements, cabinet quantities and the objects you need to store. Door swing, skirting, sockets and access routes all affect the layout. Before sampling, agree the external dimensions, internal divisions and hardware positions so appearance and everyday use follow the same plan.","bodyZh":"提供空间尺寸、柜体数量和收纳需求，是项目的起点。开门方向、踢脚线、插座位置与搬运通道，都需要纳入布局考虑。打样前确认外部尺寸、内部层板分区及五金安装位置，让外观比例与日常使用相互配合。"},{"imageUrl":"/images/xj-material-v2.jpg","altEn":"Brushed metal and muted finishes — AI design concept","altZh":"拉丝金属与柔和表面色泽 · AI 设计示意","titleEn":"Choose the material and finish","titleZh":"材料与色泽，一起打磨","bodyEn":"Stainless steel and cold-rolled steel offer different starting points for a cabinet. Discuss the room environment, material grade, sheet thickness and finish together. A physical sample helps confirm colour, sheen and texture; screens and room lighting can change how a finish appears.","bodyZh":"不锈钢与冷轧钢，为金属柜带来不同的材料选择。结合使用环境，逐项沟通材质牌号、板材厚度与表面处理方案。通过实物样板确认颜色、光泽和触感，减少屏幕显示与空间光线带来的观感差异。"},{"imageUrl":"/images/xj-factory-v2.jpg","altEn":"Metal cabinet fabrication setting — AI illustration","altZh":"金属柜加工环境 · AI 示意图","titleEn":"Turn drawings into components","titleZh":"成型与表面，落实细节","bodyEn":"Cutting, bending and joining turn sheet material into cabinet components. Edge treatment, hole positions and fixing points deserve as much attention as the visible surfaces. Agree the forming and finishing sequence against the approved sample, including how exposed edges and contact areas should be handled.","bodyZh":"板材经过开料、折弯与连接，逐步形成柜体部件。除了可见表面，边缘处理、孔位与连接点同样影响装配效果。以确认样板为参照，沟通成型和表面处理顺序，并明确外露边缘、日常接触部位等细节要求。"},{"imageUrl":"/images/xj-kitchen-3.jpg","altEn":"Completed cabinet fronts and alignment — AI design concept","altZh":"成品柜门与整体对齐效果 · AI 设计示意","titleEn":"Check the details, plan the journey","titleZh":"装配检验，妥善交付","bodyEn":"Agree checks for cabinet dimensions, door gaps, drawer movement and visible finishes. Packing should suit the cabinet structure and the planned transport route, with attention to corners, surfaces and loose hardware. Confirm assembly format, carton labels and the packing list before dispatch arrangements are made.","bodyZh":"围绕柜体尺寸、门缝均匀度、抽屉开合与表面外观，确认成品检验项目。包装方式结合柜体结构及运输路线，关注边角、饰面与独立五金的保护。发运安排前，明确整装或拆装形式、外箱标识与装箱清单。"}]' WHERE content_key='factory_capabilities' AND (en IS NULL OR TRIM(en) IN ('','[]')) AND (zh IS NULL OR TRIM(zh) IN ('','[]'));

INSERT INTO sf_content(content_key,ru,en,zh) SELECT 'factory_news','','[]','[]' WHERE NOT EXISTS (SELECT 1 FROM sf_content WHERE content_key='factory_news');

UPDATE sf_content SET en=CONCAT('[{"date":"2026-10-10","titleEn":"Steel, colour and the feel of home","titleZh":"金属柜，也可以有温度：材料与饰面的选择","imageUrl":"/images/xj-material-v2.jpg","altEn":"Material tones and brushed metal texture — AI design concept","altZh":"材料色调与拉丝金属肌理 · AI 设计示意","bodyEn":"The character of a metal cabinet comes from more than its material. Colour, sheen, edge details and the light around it work together. Warm ivory can soften a kitchen, while muted green or a brushed metal accent can give a room a quieter sense of contrast.',CHAR(92),'n',CHAR(92),'nStart by describing where the cabinet will live. A bedroom, a bathroom and a sheltered outdoor area have different conditions. Discuss the metal grade, coating system, hardware and maintenance expectations with the team, rather than choosing on colour alone.',CHAR(92),'n',CHAR(92),'nA finish sample is especially helpful alongside the actual floor, wall and worktop. Look at it in daylight and under the lighting you use in the evening. Confirm an approved physical sample before production, because a photograph or a screen cannot provide an exact colour reference.',CHAR(92),'n',CHAR(92),'nFor an initial enquiry, send a room photo or mood reference, your preferred colours and the intended location. We can use these details to discuss a coherent material and finish direction for your project.","bodyZh":"金属柜的气质，不只由材料决定。颜色、光泽、收边细节和周围的光线，共同构成空间的感受。暖象牙白可以柔化厨房氛围，低饱和绿色或局部拉丝金属，则能为家居带来安静而有层次的对比。',CHAR(92),'n',CHAR(92),'n选择之前，先说明柜子将被放在哪里。卧室、浴室与有遮蔽的户外区域，使用条件各有不同。应结合环境，与团队沟通金属牌号、涂层体系、五金配置及日常维护要求，而不只是挑选一种好看的颜色。',CHAR(92),'n',CHAR(92),'n实物饰面样板，适合放在实际的地板、墙面和台面旁对照。分别观察自然光与晚间灯光下的效果，并在生产前确认认可样板；照片和屏幕显示不宜作为精确的颜色依据。',CHAR(92),'n',CHAR(92),'n初次咨询时，可以发送空间照片或风格参考、偏好的色系以及使用位置。我们会以这些信息为起点，一起讨论适合项目的材料与饰面方向。","published":true},{"date":"2026-10-10","titleEn":"From a room sketch to a clearer cabinet brief","titleZh":"从一张空间草图开始：定制柜沟通指南","imageUrl":"/images/xj-wardrobe-v2.jpg","altEn":"Bedroom wardrobe layout — AI design concept","altZh":"卧室衣柜布局 · AI 设计示意","bodyEn":"A useful cabinet brief begins with how you live. In a wardrobe, the balance between hanging space, drawers and shelves matters as much as the overall width. In a kitchen, appliance positions and the way doors open affect how comfortably the room works.',CHAR(92),'n',CHAR(92),'nA simple annotated sketch can help the conversation move forward. Include wall widths, ceiling height and any beams, pipes or sockets. Note the measurements that still need checking on site, and identify the person responsible for confirming final dimensions.',CHAR(92),'n',CHAR(92),'nNext, agree the internal arrangement, handles or opening method, and the material and colour reference. Where sampling is needed, use it to review proportions, touch points and the agreed hardware before confirming a larger order.',CHAR(92),'n',CHAR(92),'nSend the cabinet type, approximate dimensions, quantity and delivery city with your enquiry. Drawings, specifications, pricing and the delivery plan can then be discussed together; final production and lead time follow the confirmed order details.","bodyZh":"一份有用的定制需求，首先描述真实的生活方式。衣柜里长短衣区、抽屉与层板的比例，和柜体总宽度一样重要；厨房中电器的位置、柜门打开的方向，也会影响使用是否顺手。',CHAR(92),'n',CHAR(92),'n带有尺寸标注的简单草图，就能帮助沟通向前推进。写明墙面宽度、层高，以及梁柱、管线或插座的位置。对仍需现场复核的尺寸做出标记，并明确最终尺寸由谁确认。',CHAR(92),'n',CHAR(92),'n接下来，再讨论内部布局、把手或开合方式，以及材质和颜色参照。需要打样的项目，可通过样品检查整体比例、常接触部位和约定五金，再决定后续订单细节。',CHAR(92),'n',CHAR(92),'n咨询时，请一并提供柜类、大致尺寸、数量与交付城市。图纸、配置、报价和交付安排可以结合讨论；实际生产方案与交期，以最终确认的订单信息为准。","published":true},{"date":"2026-10-10","titleEn":"The small details before a cabinet leaves","titleZh":"交付之前：值得逐项确认的装配与包装细节","imageUrl":"/images/xj-kitchen-3.jpg","altEn":"Cabinet doors and finished kitchen details — AI design concept","altZh":"柜门与厨房成品细节 · AI 设计示意","bodyEn":"A cabinet should be considered as an assembled object, not only as a collection of panels. Door alignment, smooth drawer travel and the fit of visible joints all influence daily use. Defining inspection points in advance gives both sides a shared reference.',CHAR(92),'n',CHAR(92),'nDiscuss which dimensions and functions need checking against the approved drawing or sample. Visible surfaces, edge treatment and hardware placement should be included where relevant. Any project-specific checks or inspection reports need to be agreed with the order.',CHAR(92),'n',CHAR(92),'nPacking deserves the same attention. Large panels, corners and finished surfaces need suitable protection, while loose hardware should be identified and kept with the relevant components. Assembly format, handling conditions and the transport route help determine the packing approach.',CHAR(92),'n',CHAR(92),'nBefore arranging delivery, confirm the receiving address, access restrictions, carton labels and packing list. Share any site-specific requirements early so that the cabinet and its delivery plan can be considered together.","bodyZh":"看待一组柜子，不能只看单块板材。柜门是否对齐、抽屉开合是否顺畅、可见连接处是否协调，都会影响日常体验。提前约定检验项目，可以让双方拥有一致的检查依据。',CHAR(92),'n',CHAR(92),'n根据已确认的图纸或样品，沟通需要核对的尺寸与使用功能。外观表面、边缘处理、五金位置等，也应按项目需要纳入检查。特殊检验要求或检验报告，需在订单阶段一并明确。',CHAR(92),'n',CHAR(92),'n包装同样值得认真讨论。大面板、边角与饰面需要适合的保护，独立五金应做好识别，并与对应部件配套。整装或拆装形式、搬运条件及运输路线，共同影响包装方案的选择。',CHAR(92),'n',CHAR(92),'n安排交付前，请核对收货地址、现场通道限制、外箱标识与装箱清单。尽早提供项目现场的特殊要求，让产品方案与交付安排能够一起考虑。","published":true}]'),zh=CONCAT('[{"date":"2026-10-10","titleEn":"Steel, colour and the feel of home","titleZh":"金属柜，也可以有温度：材料与饰面的选择","imageUrl":"/images/xj-material-v2.jpg","altEn":"Material tones and brushed metal texture — AI design concept","altZh":"材料色调与拉丝金属肌理 · AI 设计示意","bodyEn":"The character of a metal cabinet comes from more than its material. Colour, sheen, edge details and the light around it work together. Warm ivory can soften a kitchen, while muted green or a brushed metal accent can give a room a quieter sense of contrast.',CHAR(92),'n',CHAR(92),'nStart by describing where the cabinet will live. A bedroom, a bathroom and a sheltered outdoor area have different conditions. Discuss the metal grade, coating system, hardware and maintenance expectations with the team, rather than choosing on colour alone.',CHAR(92),'n',CHAR(92),'nA finish sample is especially helpful alongside the actual floor, wall and worktop. Look at it in daylight and under the lighting you use in the evening. Confirm an approved physical sample before production, because a photograph or a screen cannot provide an exact colour reference.',CHAR(92),'n',CHAR(92),'nFor an initial enquiry, send a room photo or mood reference, your preferred colours and the intended location. We can use these details to discuss a coherent material and finish direction for your project.","bodyZh":"金属柜的气质，不只由材料决定。颜色、光泽、收边细节和周围的光线，共同构成空间的感受。暖象牙白可以柔化厨房氛围，低饱和绿色或局部拉丝金属，则能为家居带来安静而有层次的对比。',CHAR(92),'n',CHAR(92),'n选择之前，先说明柜子将被放在哪里。卧室、浴室与有遮蔽的户外区域，使用条件各有不同。应结合环境，与团队沟通金属牌号、涂层体系、五金配置及日常维护要求，而不只是挑选一种好看的颜色。',CHAR(92),'n',CHAR(92),'n实物饰面样板，适合放在实际的地板、墙面和台面旁对照。分别观察自然光与晚间灯光下的效果，并在生产前确认认可样板；照片和屏幕显示不宜作为精确的颜色依据。',CHAR(92),'n',CHAR(92),'n初次咨询时，可以发送空间照片或风格参考、偏好的色系以及使用位置。我们会以这些信息为起点，一起讨论适合项目的材料与饰面方向。","published":true},{"date":"2026-10-10","titleEn":"From a room sketch to a clearer cabinet brief","titleZh":"从一张空间草图开始：定制柜沟通指南","imageUrl":"/images/xj-wardrobe-v2.jpg","altEn":"Bedroom wardrobe layout — AI design concept","altZh":"卧室衣柜布局 · AI 设计示意","bodyEn":"A useful cabinet brief begins with how you live. In a wardrobe, the balance between hanging space, drawers and shelves matters as much as the overall width. In a kitchen, appliance positions and the way doors open affect how comfortably the room works.',CHAR(92),'n',CHAR(92),'nA simple annotated sketch can help the conversation move forward. Include wall widths, ceiling height and any beams, pipes or sockets. Note the measurements that still need checking on site, and identify the person responsible for confirming final dimensions.',CHAR(92),'n',CHAR(92),'nNext, agree the internal arrangement, handles or opening method, and the material and colour reference. Where sampling is needed, use it to review proportions, touch points and the agreed hardware before confirming a larger order.',CHAR(92),'n',CHAR(92),'nSend the cabinet type, approximate dimensions, quantity and delivery city with your enquiry. Drawings, specifications, pricing and the delivery plan can then be discussed together; final production and lead time follow the confirmed order details.","bodyZh":"一份有用的定制需求，首先描述真实的生活方式。衣柜里长短衣区、抽屉与层板的比例，和柜体总宽度一样重要；厨房中电器的位置、柜门打开的方向，也会影响使用是否顺手。',CHAR(92),'n',CHAR(92),'n带有尺寸标注的简单草图，就能帮助沟通向前推进。写明墙面宽度、层高，以及梁柱、管线或插座的位置。对仍需现场复核的尺寸做出标记，并明确最终尺寸由谁确认。',CHAR(92),'n',CHAR(92),'n接下来，再讨论内部布局、把手或开合方式，以及材质和颜色参照。需要打样的项目，可通过样品检查整体比例、常接触部位和约定五金，再决定后续订单细节。',CHAR(92),'n',CHAR(92),'n咨询时，请一并提供柜类、大致尺寸、数量与交付城市。图纸、配置、报价和交付安排可以结合讨论；实际生产方案与交期，以最终确认的订单信息为准。","published":true},{"date":"2026-10-10","titleEn":"The small details before a cabinet leaves","titleZh":"交付之前：值得逐项确认的装配与包装细节","imageUrl":"/images/xj-kitchen-3.jpg","altEn":"Cabinet doors and finished kitchen details — AI design concept","altZh":"柜门与厨房成品细节 · AI 设计示意","bodyEn":"A cabinet should be considered as an assembled object, not only as a collection of panels. Door alignment, smooth drawer travel and the fit of visible joints all influence daily use. Defining inspection points in advance gives both sides a shared reference.',CHAR(92),'n',CHAR(92),'nDiscuss which dimensions and functions need checking against the approved drawing or sample. Visible surfaces, edge treatment and hardware placement should be included where relevant. Any project-specific checks or inspection reports need to be agreed with the order.',CHAR(92),'n',CHAR(92),'nPacking deserves the same attention. Large panels, corners and finished surfaces need suitable protection, while loose hardware should be identified and kept with the relevant components. Assembly format, handling conditions and the transport route help determine the packing approach.',CHAR(92),'n',CHAR(92),'nBefore arranging delivery, confirm the receiving address, access restrictions, carton labels and packing list. Share any site-specific requirements early so that the cabinet and its delivery plan can be considered together.","bodyZh":"看待一组柜子，不能只看单块板材。柜门是否对齐、抽屉开合是否顺畅、可见连接处是否协调，都会影响日常体验。提前约定检验项目，可以让双方拥有一致的检查依据。',CHAR(92),'n',CHAR(92),'n根据已确认的图纸或样品，沟通需要核对的尺寸与使用功能。外观表面、边缘处理、五金位置等，也应按项目需要纳入检查。特殊检验要求或检验报告，需在订单阶段一并明确。',CHAR(92),'n',CHAR(92),'n包装同样值得认真讨论。大面板、边角与饰面需要适合的保护，独立五金应做好识别，并与对应部件配套。整装或拆装形式、搬运条件及运输路线，共同影响包装方案的选择。',CHAR(92),'n',CHAR(92),'n安排交付前，请核对收货地址、现场通道限制、外箱标识与装箱清单。尽早提供项目现场的特殊要求，让产品方案与交付安排能够一起考虑。","published":true}]') WHERE content_key='factory_news' AND (en IS NULL OR TRIM(en) IN ('','[]')) AND (zh IS NULL OR TRIM(zh) IN ('','[]'));

UPDATE sf_content SET en='A considered cabinet starts long before assembly. From room dimensions and material samples to door alignment and packing, each stage needs a clear reference. These four steps outline the details to discuss with our team; materials, specifications, inspection requirements and delivery schedules are confirmed for each project.',zh='一组好用的柜子，从装配之前就开始认真推敲。从空间尺寸、材料样板，到门缝调整、包装方式，每一步都需要清晰的确认依据。以下四个环节，帮助你了解项目沟通的重点；具体材料、工艺配置、检验要求与交期，以双方确认的项目方案为准。' WHERE content_key='factory_process' AND en='Materials, dimensions, finishes and hardware are agreed before production. Share your drawings and quantities with us to discuss sampling, metal forming, surface finishing, assembly, inspection and packing. Capacity and delivery schedules are confirmed for each order.' AND zh='生产前逐项确认材料、尺寸、表面处理与五金配置。欢迎提供图纸和数量，沟通打样、金属成型、表面处理、组装、检验和包装。具体产能与交期按每个订单确认。';
